6	    Text,
7	    Title,
8	} from '@mantine/core';
9	import type { GameDayType } from 'prisma/zod/schemas/models/GameDay.schema';
10	
11	import { GameDayLink } from '@/components/GameDayLink/GameDayLink';
12	import { Team } from '@/components/Team/Team';
13	import { formatDate } from '@/lib/dates';
14	import { getGameWinnersFromTeams, getTeamResultState } from '@/lib/gameResult';
15	import { TeamPlayerType } from '@/types';
16	
17	export interface Props {
18	    gameDay: GameDayType;
19	    prevGameDay: GameDayType | null;
20	    nextGameDay: GameDayType | null;
21	    teamA: TeamPlayerType[];
22	    teamB: TeamPlayerType[];
23	}
24	
25	export const GameDaySummary = ({
26	    gameDay,
27	    prevGameDay,
28	    nextGameDay,
29	    teamA,
30	    teamB,
31	}: Props) => {
32	    const winner = getGameWinnersFromTeams(teamA, teamB);
33	    const noGame = gameDay.game ? `` : `No game`;
34	    const comment = gameDay.comment ? `(${gameDay.comment})` : ``;
35	    const maxTeamSize = Math.max(teamA.length, teamB.length);
36	    const navSlotWidth = '2rem';
37	
38	    return (
39	        <Flex direction="column" gap="sm">
40	            <Group justify="space-between" gap="xs">
41	                <Box w={navSlotWidth} ta="center">
42	                    {prevGameDay ?
43	                        <GameDayLink gameDay={prevGameDay} format="left-arrow" /> :
44	                        <Box data-testid="game-day-prev-placeholder" aria-hidden="true" w={navSlotWidth} />}
45	                </Box>
46	                <Title order={1}>{formatDate(gameDay.date)}</Title>
47	                <Box w={navSlotWidth} ta="center">
48	                    {nextGameDay ?
49	                        <GameDayLink gameDay={nextGameDay} format="right-arrow" /> :
50	                        <Box data-testid="game-day-next-placeholder" aria-hidden="true" w={navSlotWidth} />}
51	                </Box>
52	            </Group>
53	            {(
54	                <Text ta="center">
55	                    {[noGame, comment].join(' ').trim()}
56	                </Text>
57	            )}
58	            {gameDay.game ?
59	                (<SimpleGrid cols={{ base: 2, lg: 1 }} spacing="md">
60	                    <Team
61	                        team={teamA}
62	                        teamName="A"
63	                        maxTeamSize={maxTeamSize}
64	                        result={getTeamResultState('A', winner)}
65	                        hasBibs={gameDay.bibs === 'A'}
66	                    />
67	                    <Team
68	                        team={teamB}
69	                        teamName="B"
70	                        maxTeamSize={maxTeamSize}
71	                        result={getTeamResultState('B', winner)}
72	                        hasBibs={gameDay.bibs === 'B'}
73	                    />
74	                </SimpleGrid>) : null}
75	        </Flex>
76	    );
77	};
